function ChooseGender:SetButtonActive(isVisible)
    KTool.SetActive(self.ManBtn.gameObject, isVisible)
    KTool.SetActive(self.WomanBtn.gameObject, isVisible)
    if self.ManNameRoll then
        local alpha = 1
        if isVisible then
            alpha = 0
        end
        KTool.GetOrAddComponent(self.ManNameRoll.gameObject, typeof(CanvasGroup)):DOFade(alpha, 1.5):OnComplete(function()
            KTool.SetActive(self.ManNameRoll.gameObject, isReadOnly and not isVisible)
        end)
        KTool.GetOrAddComponent(self.WomanNameRoll.gameObject, typeof(CanvasGroup)):DOFade(alpha, 1.5):OnComplete(function()
            KTool.SetActive(self.WomanNameRoll.gameObject, isReadOnly and not isVisible)
        end)
    end
end

